export function parseMakerPullInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedMakerPullInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 15) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 15,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      caller: getNextAccount(),
      vault: getNextAccount(),
      bookRecord: getNextAccount(),
      custody: getNextAccount(),
      seat: getNextAccount(),
      eventsProgram: getNextAccount(),
      eventsConfig: getNextAccount(),
      series: getNextAccount(),
      market: getNextAccount(),
      venueBook: getNextAccount(),
      ledger: getNextAccount(),
      mvault: getNextAccount(),
      collateralMint: getNextAccount(),
      tokenProgram: getNextAccount(),
      eventsEventAuthority: getNextAccount(),
    },
    data: getMakerPullInstructionDataDecoder().decode(instruction.data),
  };
}
